// jsPDF's standard fonts (Helvetica/Times/Courier) use WinAnsiEncoding, which
// has no glyph for ₹ — it silently renders as a stray quote mark instead.
// Embedding a custom font just for one glyph isn't worth the extra weight, so
// every PDF generated by this app spells out "Rs." instead of reusing
// formatINR's ₹ symbol. Shared here so every PDF (audit report, receipts, …)
// gets this right without re-discovering the same glyph gotcha.
const inrNumber = new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 });
export function formatINRForPdf(amount: number): string {
  return `Rs. ${inrNumber.format(amount)}`;
}

// Same maroon as --brand in globals.css (light theme) — jsPDF needs a raw RGB
// triple, not a CSS var, so it's duplicated here rather than shared with the
// stylesheet.
export const PDF_BRAND_RGB: [number, number, number] = [140, 39, 67];
export const PDF_INK_RGB: [number, number, number] = [30, 30, 30];
export const PDF_FAINT_RGB: [number, number, number] = [110, 110, 110];

const ONES = [
  "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
  "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen",
];
const TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];

function twoDigitWords(n: number): string {
  if (n < 20) return ONES[n];
  const tens = Math.floor(n / 10);
  const ones = n % 10;
  return TENS[tens] + (ones ? ` ${ONES[ones]}` : "");
}

function threeDigitWords(n: number): string {
  const hundreds = Math.floor(n / 100);
  const rest = n % 100;
  return (hundreds ? `${ONES[hundreds]} Hundred${rest ? " " : ""}` : "") + (rest ? twoDigitWords(rest) : "");
}

/**
 * Spells out a whole rupee amount the way an Indian receipt conventionally
 * does — Indian numbering (crore/lakh/thousand), not the Western
 * million/billion grouping. Paise are dropped since every amount in this app
 * is already a whole rupee figure.
 */
export function numberToIndianWords(amount: number): string {
  const n = Math.round(Math.abs(amount));
  if (n === 0) return "Zero";
  let rem = n;
  const crore = Math.floor(rem / 10000000);
  rem %= 10000000;
  const lakh = Math.floor(rem / 100000);
  rem %= 100000;
  const thousand = Math.floor(rem / 1000);
  rem %= 1000;
  const hundreds = rem;

  const parts: string[] = [];
  if (crore) parts.push(`${threeDigitWords(crore)} Crore`);
  if (lakh) parts.push(`${threeDigitWords(lakh)} Lakh`);
  if (thousand) parts.push(`${threeDigitWords(thousand)} Thousand`);
  if (hundreds) parts.push(threeDigitWords(hundreds));
  return parts.join(" ");
}
